/**
 * Shared types used across automations, agents, and other EDK domains.
 */
import type { AppField } from "../../../core/types/app.js";
import type { FieldRef } from "../../../catalog/types.js";
import type { UnsafePlatformId } from "../../../core/platform-id.js";
import type { Ref, ValueOrRef } from "../ref.js";
import type { Attachment } from "./platform.js";
export type HttpMethod = "GET" | "POST" | "PUT" | "DELETE";
export interface BasicAuth {
    type: "basic";
    username: ValueOrRef<string>;
    password: ValueOrRef<string>;
}
export interface BearerAuth {
    type: "bearer";
    /**
     * Bearer token. Accepts a raw string (literal or environment-rewritten
     * placeholder), a task/trigger ref (e.g. `ctx.actions.login.token`), or
     * a `secret(...)` ref that serializes to Mobius's secret-reference
     * shape. Every real integration uses a secret; the raw-string form
     * exists only for the literal / placeholder case.
     */
    token: ValueOrRef<string>;
}
export interface OAuthAuth {
    type: "oauth";
    url: ValueOrRef<string>;
    clientId: ValueOrRef<string>;
    clientSecret: ValueOrRef<string>;
}
export type ApiAuthorization = BasicAuth | BearerAuth | OAuthAuth;
export interface JsonBody {
    type: "json";
    json: unknown;
}
export interface FormBody {
    type: "form";
    values: Array<{
        key: string;
        value: string;
    }>;
}
export interface CustomBody {
    type: "custom";
    body: string;
    contentType: string;
}
/**
 * One entry in a multipart body. Either a text part (any value, optionally
 * referenced from upstream data) or a file part backed by exactly one of
 * `attachmentId`, `attachment`, or `file`. File-source slots accept a
 * `Ref<…>` only — the platform rejects literal values in those slots, so
 * the type forbids them at compile time.
 */
export interface MultipartTextPart {
    name: string;
    value: ValueOrRef<string>;
}
export type MultipartFilePart = {
    name: string;
    attachmentId: Ref<string>;
    attachment?: never;
    file?: never;
} | {
    name: string;
    attachment: Ref<Attachment>;
    attachmentId?: never;
    file?: never;
} | {
    name: string;
    file: Ref<unknown>;
    attachmentId?: never;
    attachment?: never;
};
export type MultipartPart = MultipartTextPart | MultipartFilePart;
export interface MultipartBody {
    type: "multipart";
    parts: ReadonlyArray<MultipartPart>;
}
export type ApiBody = JsonBody | FormBody | CustomBody | MultipartBody;
export type SortDirection = "ASC" | "DESC";
/** One sort clause (field id + direction). Use {@link asc}, {@link desc}, or {@link sortBy}. */
export interface SortOrder<Field = AppField> {
    field: Field;
    direction: SortDirection;
}
export declare function asc<Field extends AppField | FieldRef | UnsafePlatformId>(field: Field): SortOrder<Field>;
export declare function desc<Field extends AppField | FieldRef | UnsafePlatformId>(field: Field): SortOrder<Field>;
/** Multi-field sort (order is significant). Serializes to `Sort.orders` for Mobius. */
export declare function sortBy<Field>(...orders: SortOrder<Field>[]): readonly SortOrder<Field>[];
/**
 * Serialize an authored `SortOrder | readonly SortOrder[]` to the
 * platform's `Sort` JSON shape: `{ orders: [{ field: <id>, direction }] }`.
 * Returns `undefined` when `sort` is null/undefined or doesn't match
 * the expected shape — callers can then omit the wire field entirely.
 *
 * Lifted from `automations/serializer/task-serializer.ts` so every
 * tool surface that accepts a sort (automation `recordSearch`, agent
 * search tools, etc.) emits the same wire shape through the same
 * code path.
 */
export declare function serializeSortToWire(sort: unknown): Record<string, unknown> | undefined;
export type AiAgentOutputType = "text" | "json";
export interface AiJsonFieldDef {
    type: "text" | "number" | "boolean" | "date";
    description?: string;
}
